import 'dart:async';
import 'package:flutter/material.dart';
import '../../core/network/api_client.dart';
import 'customer_detail_page.dart';

class CustomersPage extends StatefulWidget{const CustomersPage({super.key,required this.client});final ApiClient client;@override State<CustomersPage> createState()=>_CustomersPageState();}
class _CustomersPageState extends State<CustomersPage>{late Future<Map<String,dynamic>> future;final search=TextEditingController();Timer? timer;@override void initState(){super.initState();load();}@override void dispose(){timer?.cancel();search.dispose();super.dispose();}void load()=>setState(()=>future=widget.client.customers(search:search.text.trim()));void changed(String _){timer?.cancel();timer=Timer(const Duration(milliseconds:450),load);}
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('مشتریان'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh_rounded))]),body:Column(children:[Padding(padding:const EdgeInsets.all(16),child:SearchBar(controller:search,hintText:'جست‌وجوی نام، ایمیل یا شماره',leading:const Icon(Icons.search_rounded),onChanged:changed)),Expanded(child:FutureBuilder<Map<String,dynamic>>(future:future,builder:(context,snapshot){if(snapshot.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(snapshot.hasError)return Center(child:FilledButton(onPressed:load,child:const Text('تلاش دوباره')));final data=snapshot.data!;final items=data['items'] as List? ?? const [];if(items.isEmpty)return const Center(child:Text('مشتری ثبت‌شده‌ای پیدا نشد.'));return RefreshIndicator(onRefresh:()async=>load(),child:ListView.builder(padding:const EdgeInsets.fromLTRB(16,0,16,24),itemCount:items.length,itemBuilder:(context,index){final c=Map<String,dynamic>.from(items[index] as Map);final full='${c['first_name']??''} ${c['last_name']??''}'.trim();return Card(child:ListTile(onTap:()async{await Navigator.push(context,MaterialPageRoute(builder:(_)=>CustomerDetailPage(client:widget.client,customerId:(c['id'] as num).toInt())));load();},leading:CircleAvatar(backgroundImage:c['avatar']==null?null:NetworkImage(c['avatar'].toString()),child:c['avatar']==null?const Icon(Icons.person_outline):null),title:Text(full.isEmpty?'مشتری #${c['id']}':full),subtitle:Text('${c['phone'].toString().isEmpty?c['email']:c['phone']}\n${c['orders_count']} سفارش  •  ${c['total_spent']}'),isThreeLine:true,trailing:const Icon(Icons.chevron_left_rounded)));}));}))]));}
